#include "cfdx/physics/thermophysical_models.h"
#include "cfdx/physics/turbulence_models.h"
#include "common/test_harness.h"
#include <cmath>
using namespace cfdx::physics; using namespace cfdx::testing;
int main() {
 run_case("scalar_property_models", [] { ScalarPropertyControls c; c.reference_value=10.0; EXPECT_NEAR(evaluate_scalar_property(c,500),10,1e-12); c.model=ScalarPropertyModel::LINEAR;c.coefficients={0.1};EXPECT_NEAR(evaluate_scalar_property(c,400),20,1e-12);c.model=ScalarPropertyModel::POLYNOMIAL;c.coefficients={10,.1,.001};EXPECT_NEAR(evaluate_scalar_property(c,400),30,1e-12);c.model=ScalarPropertyModel::POWER_LAW;c.reference_value=4;c.exponent=1;EXPECT_NEAR(evaluate_scalar_property(c,600),8,1e-12);c.model=ScalarPropertyModel::EXPONENTIAL;c.reference_value=2;c.exponent=.01;EXPECT_NEAR(evaluate_scalar_property(c,400),2*std::exp(.01*(400-300)/300),1e-12);c.model=ScalarPropertyModel::ARRHENIUS;c.reference_value=2;c.activation_temperature=1000;EXPECT_NEAR(evaluate_scalar_property(c,600),2*std::exp(1000*(1.0/300-1.0/600)),1e-10);});
 run_case("tabulated_property_policies", [] {ScalarPropertyControls c;c.model=ScalarPropertyModel::TABLE;c.table.temperature={300,400,500};c.table.value={10,20,30};EXPECT_NEAR(evaluate_scalar_property(c,450),25,1e-12);EXPECT_NEAR(evaluate_scalar_property(c,200),10,1e-12);c.table.extrapolation=ExtrapolationPolicy::LINEAR;EXPECT_NEAR(evaluate_scalar_property(c,250),5,1e-12);c.table.extrapolation=ExtrapolationPolicy::REJECT;bool threw=false;try{(void)evaluate_scalar_property(c,200);}catch(...){threw=true;}EXPECT_TRUE(threw);});
 run_case("density_and_enthalpy", [] {DensityControls d;d.rho0=1000;d.model=DensityModel::BOUSSINESQ;d.beta=1e-3;EXPECT_NEAR(evaluate_density(d,310),990,1e-12);bool threw=false;try{(void)evaluate_density(d,450);}catch(...){threw=true;}EXPECT_TRUE(threw);d.model=DensityModel::IDEAL_GAS;d.gas_constant=287.05;EXPECT_NEAR(evaluate_density(d,300,101325),101325/(287.05*300),1e-12);ThermophysicalProperties p;p.heat_capacity.reference_value=1000;EXPECT_NEAR(p.enthalpy(400,300,64),100000,1e-8);p.heat_capacity.model=ScalarPropertyModel::LINEAR;p.heat_capacity.coefficients={2};EXPECT_NEAR(p.enthalpy(400,300,8),110000,1e-8);p.heat_capacity.model=ScalarPropertyModel::TABLE;p.heat_capacity.table.temperature={300,400,500};p.heat_capacity.table.value={1000,1200,1400};EXPECT_NEAR(p.enthalpy(500,300),240000,1e-8);p.heat_capacity.model=ScalarPropertyModel::LINEAR;p.heat_capacity.reference_value=1000;p.heat_capacity.coefficients={2};EXPECT_NEAR((p.cp(400)-p.cp(300))/100,2,1e-12);});
 run_case("thermal_turbulence_coupling", [] {EXPECT_NEAR(turbulent_thermal_diffusivity(.01,1,.9),.0111111111111111,1e-12);EXPECT_NEAR(k_epsilon_eddy_viscosity(4,2),.72,1e-12);EXPECT_NEAR(rng_kepsilon_eddy_viscosity(4,2),.676,1e-12);EXPECT_NEAR(komega_eddy_viscosity(2,4),.5,1e-12);EXPECT_NEAR(sst_eddy_viscosity(1,2,1),.31,1e-12);EXPECT_NEAR(sst_eddy_viscosity(1,2,1,.31,.5),.5,1e-12);EXPECT_NEAR(spalart_allmaras_nu_t(1e-4,.01,1e-5),1e-4*std::pow(10.,3)/(std::pow(10.,3)+std::pow(7.1,3)),1e-12);EXPECT_NEAR(spalart_allmaras_nu_t(-1e-4,.01,1e-5),0,1e-15);bool threw=false;try{(void)spalart_allmaras_nu_t(-1e-4,.01,1e-5,NegativeNuTildePolicy::REJECT);}catch(...){threw=true;}EXPECT_TRUE(threw);EXPECT_NEAR(smagorinsky_nu_t(.17,.1,10),.00289,1e-12);EXPECT_NEAR(wale_nu_t(.5,.1,10),.025,1e-12);EXPECT_TRUE(static_cast<int>(implementation_kind(AdvancedTurbulenceModel::SST))==static_cast<int>(TurbulenceImplementationKind::TRANSPORT_MODEL));EXPECT_TRUE(has_transport_equation(AdvancedTurbulenceModel::KEPSILON));EXPECT_TRUE(has_transport_equation(AdvancedTurbulenceModel::RNG_KEPSILON));EXPECT_TRUE(has_transport_equation(AdvancedTurbulenceModel::KOMEGA));EXPECT_TRUE(has_transport_equation(AdvancedTurbulenceModel::SPALART_ALLMARAS));EXPECT_TRUE(!has_transport_equation(AdvancedTurbulenceModel::SMAGORINSKY));EXPECT_NEAR(des_length_scale(.5,.2,.65),.13,1e-12);EXPECT_NEAR(ddes_length_scale_from_rd(.5,.2,.65,0),.13,1e-12);EXPECT_NEAR(ddes_length_scale_from_rd(.5,.2,.65,1),.5,1e-12);EXPECT_NEAR(iddes_length_scale_from_rd(.5,.2,.65,0,1),.13,1e-12);EXPECT_NEAR(iddes_length_scale_from_rd(.5,.2,.65,1,1),.5,1e-12);EXPECT_NEAR(ddes_shielding(0),1,1e-12);EXPECT_TRUE(ddes_shielding(1)<1e-10);EXPECT_NEAR(ddes_length_scale(.5,.2,.65,1),.13,1e-12);EXPECT_NEAR(ddes_length_scale(.5,.2,.65,0),.5,1e-12);});
 run_case("invalid_models_are_rejected", [] {bool threw=false;try{ScalarPropertyControls c;c.reference_value=-1;(void)evaluate_scalar_property(c,300);}catch(...){threw=true;}EXPECT_TRUE(threw);});
 return run_all();
}